#!/usr/bin/env bash
# PORTMASTER: chrono, Chrono Trigger.sh
# Generated by nxbootstrap. Public entry point and declarative port contract.

PORT_ID=chrono
PORT_TITLE='Chrono Trigger'
NXPORT_ID=chrono
NXPORT_TITLE='Chrono Trigger'
NXPORT_SCHEMA_VERSION=2
NXPORT_ARCH=aarch64
NXPORT_INTERPRETER=/lib/ld-linux-aarch64.so.1
NXPORT_EXECUTABLE=chrono-universal
NXPORT_ARGUMENT_MODE=game-dir-and-passthrough
NXPORT_HOME_MODE=port
NXPORT_NXEXTRACT=yes
NXPORT_NXEXTRACT_VERSION=1.2.6
NXPORT_REQUIRED_FILES='chrono-universal
libchrono.so
libc++_shared.so
assets/resources.bin
assets/001.dat
assets/Shaders/example_Simple.vsh'
NXPORT_PRIVATE_LIBRARY_PATHS=''
NXPORT_PREPARE_SCRIPT=''
NXPORT_REQUIRED_CAPABILITIES='host.portmaster
graphics.window
graphics.gles2
graphics.egl
graphics.egl-config
graphics.drawable
input.controller-mapping
input.controller-api'
NXPORT_ENABLED_QUIRKS='game.chrono.present-alpha-one
game.chrono.present-finish'
NXPORT_RUNTIME_REPORT=log-and-logo

ORIGINAL_SELF=${BASH_SOURCE[0]}
ORIGINAL_DIR=$(CDPATH= cd -- "$(dirname -- "$ORIGINAL_SELF")" 2>/dev/null && pwd -P) ||
  ORIGINAL_DIR=.
SELF=$ORIGINAL_SELF
if [[ -L $SELF ]]; then
  if command -v readlink >/dev/null 2>&1; then
    RESOLVED=$(readlink -f -- "$SELF" 2>/dev/null || true)
    if [[ -n $RESOLVED ]]; then
      SELF=$RESOLVED
    else
      link_depth=0
      while [[ -L $SELF && $link_depth -lt 16 ]]; do
        LINK=$(readlink -- "$SELF" 2>/dev/null || true)
        case $LINK in
          /*) SELF=$LINK ;;
          ?*) SELF=$(dirname -- "$SELF")/$LINK ;;
          *) break ;;
        esac
        link_depth=$((link_depth + 1))
      done
      [[ $link_depth -lt 16 ]] || exit 1
    fi
  fi
fi
SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$SELF")" 2>/dev/null && pwd -P) ||
  exit 1

TRIED=
try_port() {
  local candidate=$1 bootstrap manifest status
  shift
  TRIED="${TRIED}${TRIED:+
}$candidate"
  bootstrap=$candidate/nxbootstrap.sh
  manifest=$candidate/nxport.json
  if [[ -d $candidate && -f $bootstrap && ! -L $bootstrap &&
        -f $manifest && ! -L $manifest ]]; then
    NXPORT_GAME_DIR=$(CDPATH= cd -- "$candidate" 2>/dev/null && pwd -P) ||
      return 0
    [[ $NXPORT_GAME_DIR != / ]] || return 0
    source "$NXPORT_GAME_DIR/nxbootstrap.sh" || exit 1
    nxbootstrap_main "$@"
    status=$?
    exit "$status"
  fi
}

# Relative discovery covers PortMaster copies/symlinks without choosing a CFW.
cursor=$SCRIPT_DIR
depth=0
while [[ $depth -lt 5 ]]; do
  try_port "$cursor/$PORT_ID" "$@"
  try_port "$cursor/ports/$PORT_ID" "$@"
  try_port "$cursor/Ports/$PORT_ID" "$@"
  parent=$(dirname -- "$cursor")
  [[ $parent != "$cursor" ]] || break
  cursor=$parent
  depth=$((depth + 1))
done

for rom_root in \
  /roms /roms2 /storage/roms /userdata/roms \
  /mnt/mmc /mnt/mmc/roms /mnt/mmc/ROMS \
  /mnt/sdcard /mnt/sdcard/roms /mnt/sdcard/ROMS
do
  try_port "$rom_root/ports/$PORT_ID" "$@"
  try_port "$rom_root/Ports/$PORT_ID" "$@"
done

message="$PORT_TITLE: $PORT_ID runtime directory not found"
details="launcher=$ORIGINAL_SELF resolved=$SELF
paths tried:
$TRIED"
printf '%s\n%s\n' "$message" "$details" >&2
umask 077
for log in \
  "$ORIGINAL_DIR/${PORT_ID}-launcher-error.$$.log" \
  "$SCRIPT_DIR/${PORT_ID}-launcher-error.$$.log" \
  "${TMPDIR:-/tmp}/${PORT_ID}-launcher-error.$$.log"
do
  if (set -C; printf '%s\n%s\n' "$message" "$details" > "$log") 2>/dev/null; then
    for tty in /dev/tty0 /dev/console; do
      if [[ -c $tty && ! -L $tty ]]; then
        printf '%s; details: %s\n' "$message" "$log" > "$tty" 2>/dev/null && break
      fi
    done
    break
  fi
done
exit 1
